// Tap: bounded side queue with an explicit, VISIBLE loss policy
long drops = 0;
var tap = Channel.CreateBounded<Message>(
    new BoundedChannelOptions(1_000)
    {
        FullMode = BoundedChannelFullMode.DropOldest,
        SingleReader = true,
        AllowSynchronousContinuations = false,
    },
    dropped => Interlocked.Increment(ref drops)); // only truthful loss signal

// Analyzer runs out-of-band on its own task
_ = Task.Run(async () =>
{
    await foreach (var copy in tap.Reader.ReadAllAsync(ct))
        await analyzer.AnalyzeAsync(copy, ct);
});

// The tap itself: a send wrapper; sender and receiver are untouched
async Task SendWithTapAsync(Message m, IEndpoint primary, CancellationToken ct)
{
    tap.Writer.TryWrite(m.Snapshot());      // immutable copy; never blocks
    await primary.SendAsync(m, ct);         // original, unmodified
}
